insert into legs (season_id, n, beta, tags, team_rating, surface_text) values
((select id from seasons where year=2026), 1, 'Trail has switchbacks with loose gravel and tree roots — be careful, saw several people fall. Steep climb going into Eureka, potential to walk some of it. Easy downhill through town, followed by a tough gravel climb to the finish. Could see this leg rated very hard.', '["Loose gravel + roots", "Steep climb"]'::jsonb, 'Very Hard', 'Trail / pavement / gravel'),
((select id from seasons where year=2026), 2, 'A lot of climbs on this one. Rated moderate, but it''s definitely hard. Pay attention to turn signs and dogs. A good early leg to get the body going. 2026 watches read ~720 ft of climb, more than the figure listed.', '["Dogs", "Watch the turns"]'::jsonb, 'Hard', 'All pavement'),
((select id from seasons where year=2026), 3, 'Hard for sure. Super rocky path for the first half: a long descent that crosses a dry river bed, then it climbs again from there. Very steep climb at mile 4 with some sand barriers to get over, which are a little tricky. In 2026 that climb wasn''t groomed, so it was waist-high weeds the whole way for about half a mile. After that it''s dirt for a little longer, then pavement for the last mile and change.', '["No van access", "Rocky"]'::jsonb, null, '75% gravel/trail · 25% pavement'),
((select id from seasons where year=2026), 4, 'Starts on paved highway with moderate traffic. Mostly flat. Finishes with a descent on a rocky dirt road. Closer to easy. Not the leg for anyone sensitive to smells: you pass some chicken and cow farms that put off quite a stink. Narrow shoulder on the highway: in a couple of places it felt safer to run in the grass. The gravel downhill at the end is a lot of fun.', '["Traffic", "Narrow shoulder"]'::jsonb, 'Easy', 'Pavement / gravel'),
((select id from seasons where year=2026), 5, 'Very steep climbs with some hard descents — and beautiful views. You''ll have hills where you have to walk, followed by steep descents where you can run fast, but not too fast or you might fall. Pay attention to footing. Very challenging leg.', '["Footing", "Walk the steeps", "Views"]'::jsonb, null, '100% gravel'),
((select id from seasons where year=2026), 6, 'Easy paved highway. Rated moderate, but I would rate it easy. Nice rolling flats on pavement.', '[]'::jsonb, 'Easy', '¼ mile dirt, then all pavement'),
((select id from seasons where year=2026), 7, 'Rolling hills with two big inclines. Easy to go fast on the downhill. A lot of good shade. All trail at Hobbs, with plenty of shade. The trail is in fairly good shape, but rocks and small roots hide under leaves and pine needles: you can move, but be cautious. The first 3 miles are mostly downs and straights with a few climbs; the last 2 miles bring more switchbacks and climbs, so save your energy for the end. A fun leg! 2026 watches read ~540 ft of climb, more than the figure listed.', '["Shaded", "Rocks + roots under leaves", "Climbs in the last 2 mi"]'::jsonb, null, '100% trail'),
((select id from seasons where year=2026), 8, 'Anticipate loose rocks, exposed roots and heavy leaf coverage. Several descents and moderate climbs. Finishes with a transition to paved road leading directly to War Eagle. GPS navigation recommended for the trail (sorry Benny).', '["GPS recommended", "Rocks + roots + leaves"]'::jsonb, null, 'Mostly trail · last mile pavement'),
((select id from seasons where year=2026), 9, 'Lightly hilly countryside with a few medium-sized hills along the way. Seems moderate. Moderate climbs at the beginning and at the end, all runnable compared with other hills on this course where it''s better to walk. Hardly any shade cover, and you''re likely running it in the heat of the day, so it''s a hot one if temperatures are high. Just a long run, which is why I downgrade it to moderate.', '["No shade, hot"]'::jsonb, 'Moderate', '60% pavement · 40% gravel'),
((select id from seasons where year=2026), 10, 'You go up a gnarly hill when you reach gravel — the rock was chunky and challenging for road shoes. Back onto the highway, then gravel again. Both my favorite and least favorite leg. Rated hard, and I definitely agree. In 2026 it could have been done in road shoes, so footwear matters less than it sounds. Mostly gravel roads with a little major highway on a narrow shoulder. Some LONG sustained climbs. Lots of dogs on the route, but they all stayed on their property. 2026 watches read ~1,000 ft of climb, more than the figure listed.', '["Chunky rock", "Shoe choice matters", "Long sustained climbs", "Dogs"]'::jsonb, null, '½ mi pavement · 7 mi gravel · 1 mi pavement'),
((select id from seasons where year=2026), 11, 'Easy downhill to start. Rolling hills with a couple decent climbs. Gravel was in good shape. Turns onto Hwy 23, which is flat — but be on the lookout for traffic. 2026 watches read ~590 ft of climb, well above the figure listed.', '["Traffic on Hwy 23"]'::jsonb, null, '⅓ gravel · ⅔ pavement'),
((select id from seasons where year=2026), 12, 'Big decline at the pavement portion. The last half mile is trail and the toughest part — the stairs on the trail are slippery. 2026 watches read ~380 ft of climb, well above the figure listed.', '["Slippery stairs"]'::jsonb, null, 'Mostly gravel / pavement · last ½ mi gravel'),
((select id from seasons where year=2026), 13, 'Cross the street to the dirt road — if you go over the second bridge, you went too far. Pavement leads to a ferry pickup to cross Hwy 412, then finish with a half-mile run after. Once you reach the gravel you are most of the way to the finish; you get back on pavement for the last half mile to full mile. Fairly easy leg, rated moderate mostly because of the distance.', '["Navigation", "Hwy 412 ferry crossing"]'::jsonb, null, '⅓ pavement · ⅔ gravel'),
((select id from seasons where year=2026), 14, 'Several turns, and some of the signs were removed or hard to see. Pay attention — have the van stick with the runner on this one. Some climbs along the way. Still several turns in 2026: keep an eye out for the course signs so you don''t miss one.', '["Navigation!", "Van should shadow runner"]'::jsonb, null, '100% gravel'),
((select id from seasons where year=2026), 15, 'Pitch black. Some little rollers with one mild climb. I would rate it moderate. Not sure why this was rated hard: there are some climbs, but overall you''re going downhill. The first 3 miles of gravel were a little chunky with small rocks, so stability was tricky. I was glad when it switched to pavement and I could pick up the pace.', '["Pitch black \u2014 lights!", "Loose gravel"]'::jsonb, 'Moderate', '3 mi gravel · 4 mi pavement'),
((select id from seasons where year=2026), 16, 'Spooky as hell, but if you can get past that, a quiet and peaceful run. Rated moderate, but I would rate it easy. Dark roads. Starts out paved; mostly flat with some mild climbs. Watch for the fork at the junction of 197 and 6041: turn LEFT onto the gravel on 6041. Garmin didn''t call out that turn (it only alerted once off course) and the glow stick was easy to miss.', '["Dark + spooky", "Turn left at 197 / 6041"]'::jsonb, 'Easy', '40% pavement · 60% gravel'),
((select id from seasons where year=2026), 17, 'Appropriately moderate. The hills were nasty getting up, but you end on pavement with a consistent decline — you make up a ton of time on the downhill. Push hard on the uphill, because you can catch your breath at the end.', '["Nasty ups, fast finish"]'::jsonb, null, '75% gravel · 25% pavement'),
((select id from seasons where year=2026), 18, 'You can definitely run faster on this leg. Pay attention to turns and traffic on the final mile. Overall a flat and nice leg — more towards easy.', '["Turns + traffic, final mile"]'::jsonb, 'Easy', 'Pavement / gravel / pavement · about half and half'),
((select id from seasons where year=2026), 19, 'Leaves the city and heads out onto a paved road. Very dark. Mostly flat with some light-to-medium rolling hills. More moderate. About a third to half a mile in, the street veers left while another road continues straight, and Strava/GPS will tell you to keep straight for 2 miles. Don''t: watch for the signs and glowsticks and veer left. A good climb follows. A runner missed that turn half a mile in during 2026 and went 2 miles off course, so pay attention!', '["Very dark", "Veer left early, GPS is wrong"]'::jsonb, 'Moderate', '100% pavement'),
((select id from seasons where year=2026), 20, 'Easy breezy! A few hills. Mostly flat with a few small hills: a good leg to hold a comfortable pace and save some energy.', '[]'::jsonb, null, '100% pavement'),
((select id from seasons where year=2026), 21, 'Very easy run: smooth road and flat, with a few bridge crossings along the way. Listed as gravel, but in 2026 it was really hard-packed dirt with not much gravel on the road, a nice comfortable jog. There are a few potholes (one of us twisted an ankle in one), but not many, so just bad luck.', '["A few bridge crossings"]'::jsonb, null, 'Hard-packed dirt road · little gravel'),
((select id from seasons where year=2026), 22, 'One steady climb the whole way — very gradual, but steep at times. It just keeps going! Hard to hold the heart rate down. Be ready to climb and go slow on this one. Leans towards hard. Extremely dark and isolated, so it feels spooky. The flat stretches are short, just enough to bring the heart rate down before the climb goes on again.', '["Sustained climb", "Dark + isolated"]'::jsonb, 'Hard', 'Gravel / pavement · close to half and half'),
((select id from seasons where year=2026), 23, 'Starts off flat and smooth, but gets very rough and rugged about 3 miles in and stays that way until the end.', '["Rugged after mile 3"]'::jsonb, null, '100% gravel'),
((select id from seasons where year=2026), 24, 'About 4 miles of this is rough, loose gravel: the first part sucks, the very end is a piece of cake. The 2025 notes called it broken pavement in very bad shape; either way, pay attention to your footing. A lot of hills and very desolate. You will walk some. It felt good to get to Lake Fort Smith and be done with this one.', '["Rough loose gravel", "Desolate"]'::jsonb, null, '~4 mi rough loose gravel · smooth finish'),
((select id from seasons where year=2026), 25, 'All uphill for 1.7 miles before a constant downhill to Chester. The downhill felt like it went on forever. Rated hard, and I definitely agree. In 2026, after that opening climb the rest of the leg was very nice and smooth: a good leg overall. It''s long, which is probably why it''s rated hard.', '["1.7 mi opening climb", "Endless downhill"]'::jsonb, null, '100% pavement'),
((select id from seasons where year=2026), 26, 'Take a left onto the main road out of the parking lot, immediately beginning a substantial climb. Once you reach the summit, bear left to transition to a dirt road for your exchange. The first couple of miles are manageable, steady climbing; the last few miles are rolling hills with some tough climbs. Be prepared to walk some of them and save your energy early. Hard. Long steady climb at the end; many were walking that section.', '["Climbs right off the start"]'::jsonb, 'Hard', '100% pavement'),
((select id from seasons where year=2026), 27, 'Easily a hard rating. The hills were a beast and the terrain was difficult. There''s a huge hill between miles 5 and 6, you will likely walk some. Save yourself on the initial hills, because the last one is painful. A bunch of ups and downs: I had to walk one of the climbs in the middle as it got steep. The climb from 5.5 to 6 is super steep. Unless you''re a beast, it''s probably smarter to just walk it, because even walking I was slipping out from under myself. The one good thing about this hard trail: a lot of shade cover along the way if you''re running during the day.', '["Beast hills", "Big hill mi 5\u20136", "Shaded"]'::jsonb, 'Hard', '100% gravel'),
((select id from seasons where year=2026), 28, 'Smooth sailing! Nice paved road, beautiful views. Some substantial uphill, but still moderate overall. Rolling hills with 4 notable climbs. Starts on pavement, then switches to gravel. At midday it was 95% sun with little shade. Moderate feels fair.', '["Views"]'::jsonb, null, 'Half pavement · half gravel'),
((select id from seasons where year=2026), 29, 'Lots of rolling hills with three big climbs — every downhill was met with a climb. Windy road with very little shoulder. Would recommend a flagger. 2026 watches read ~480 ft of climb, well above the figure listed.', '["Flagger recommended", "No shoulder"]'::jsonb, null, '100% pavement'),
((select id from seasons where year=2026), 30, 'A lot of gradual climbs for the first 4–5 miles. Take your time — you''ll need it for the brutal descent into Devil''s Den: switchbacks and high traffic, with over 800 ft of descent in the last couple of miles. Highly recommend a flagger.', '["Flagger recommended", "Brutal descent", "Switchbacks + traffic"]'::jsonb, null, '100% pavement'),
((select id from seasons where year=2026), 31, 'Short trail coming out of the park with uneven terrain. Once you reach Hwy 16 it''s flat until 2.3 miles in — then you climb!! Climb the rest of the way. Walked a few stretches to keep the heart rate down.', '["Climb from mile 2.3 on"]'::jsonb, null, '½ mi trail · 3.5 mi pavement · rest gravel'),
((select id from seasons where year=2026), 32, 'Transition is about halfway, where you''ll make a left. Rolling hills throughout, followed by a short climb to the finish.', '[]'::jsonb, null, '50% pavement · 50% gravel'),
((select id from seasons where year=2026), 33, 'A lot of curves in the road towards the end and no shoulder to retreat to — be careful! Recommend a flagger.', '["Flagger recommended", "Blind curves"]'::jsonb, null, 'Pavement / gravel'),
((select id from seasons where year=2026), 34, 'Nice easy leg with a lot of descents. If you have anything left, you can make good time on this one.', '["Fast descents"]'::jsonb, null, '100% gravel'),
((select id from seasons where year=2026), 35, 'Start on dirt with a steady incline, finish on pavement with a decline. Next to a busy road — stay alert!', '["Busy road"]'::jsonb, null, '½ gravel · ½ pavement'),
((select id from seasons where year=2026), 36, 'Light rolling hills. Ferry at the Hwy 62 intersection — park your car on the same side as the runner and ferry across the street. Ends at the finish line at Prairie Grove Battlefield Park!', '["Hwy 62 ferry crossing", "FINISH!"]'::jsonb, null, 'Pavement · 1 mi gravel · pavement')
